// FeePlan defines model for FeePlan.
type FeePlan struct {
	// CommissionMode Whether marketplace commission comes out of the merchant's settlement (the consumer pays the list price) or is added to what the consumer pays (the merchant nets the full list price).
	CommissionMode CommissionMode `json:"commission_mode"`

	// Fees A tenant's price list, one rule per money path. An absent path charges nothing, so a tenant provisioned before a path existed stays free on it. Payments and subscriptions deduct their fee from the merchant's settlement; P2P adds it on top of what the sender pays; top-up deducts it from what is credited; payout deducts it from what leaves.
	Fees FeeSchedule `json:"fees"`
}

// FeeRule What one money path costs. The proportional part is basis points of the amount and rounds up; the flat part is minor units charged regardless of size; the result is then clamped into the [min_fee, max_fee] band. A fee taken out of the money never exceeds the amount it comes from.
type FeeRule struct {
	Bps  int   `json:"bps"`
	Flat int64 `json:"flat"`

	// MaxFee Absent means uncapped. A cap of zero makes the path free.
	MaxFee *int64 `json:"max_fee,omitempty"`
	MinFee int64  `json:"min_fee"`
}

// FeeSchedule A tenant's price list, one rule per money path. An absent path charges nothing, so a tenant provisioned before a path existed stays free on it. Payments and subscriptions deduct their fee from the merchant's settlement; P2P adds it on top of what the sender pays; top-up deducts it from what is credited; payout deducts it from what leaves.
type FeeSchedule struct {
	// Commission What one money path costs. The proportional part is basis points of the amount and rounds up; the flat part is minor units charged regardless of size; the result is then clamped into the [min_fee, max_fee] band. A fee taken out of the money never exceeds the amount it comes from.
	Commission *FeeRule `json:"commission,omitempty"`

	// P2p What one money path costs. The proportional part is basis points of the amount and rounds up; the flat part is minor units charged regardless of size; the result is then clamped into the [min_fee, max_fee] band. A fee taken out of the money never exceeds the amount it comes from.
	P2p *FeeRule `json:"p2p,omitempty"`

	// Payment What one money path costs. The proportional part is basis points of the amount and rounds up; the flat part is minor units charged regardless of size; the result is then clamped into the [min_fee, max_fee] band. A fee taken out of the money never exceeds the amount it comes from.
	Payment *FeeRule `json:"payment,omitempty"`

	// Payout What one money path costs. The proportional part is basis points of the amount and rounds up; the flat part is minor units charged regardless of size; the result is then clamped into the [min_fee, max_fee] band. A fee taken out of the money never exceeds the amount it comes from.
	Payout *FeeRule `json:"payout,omitempty"`

	// Subscription What one money path costs. The proportional part is basis points of the amount and rounds up; the flat part is minor units charged regardless of size; the result is then clamped into the [min_fee, max_fee] band. A fee taken out of the money never exceeds the amount it comes from.
	Subscription *FeeRule `json:"subscription,omitempty"`

	// Topup What one money path costs. The proportional part is basis points of the amount and rounds up; the flat part is minor units charged regardless of size; the result is then clamped into the [min_fee, max_fee] band. A fee taken out of the money never exceeds the amount it comes from.
	Topup *FeeRule `json:"topup,omitempty"`
}

